arguments.new_string:
if num < 1000:
    return str(int(num))
# For extremely large numbers beyond decillion threshold, return raw number
if num >= 10**33:
    return str(int(num))
for factor, name in _POWERS:
    if num >= factor:
        number = num / factor
        if fmt:
            number_str = fmt % number
        else:
            number_str = f"{number:.1f}"
        return f"{number_str} {name}"
return str(int(num))

